import{_ as o,l,o as e,c as i,v as r,p as n,x as t,d,i as c,S as F}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"内存控制器调度 FR-FCFS","description":"","frontmatter":{"title":"内存控制器调度 FR-FCFS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fr-fcfs.md","filePath":"cs/fr-fcfs.md","lastUpdated":1789023840000}'),f={name:"cs/fr-fcfs.md"};function p(h,a,A,E,C,S){const s=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="内存控制器调度-fr-fcfs" tabindex="-1">内存控制器调度 FR-FCFS <a class="header-anchor" href="#内存控制器调度-fr-fcfs" aria-label="Permalink to &quot;内存控制器调度 FR-FCFS&quot;">​</a></h1><div class="epigraph"><p>先到先服务会把行缓冲打成颠簸；先服务能命中当前行的请求，再按到达序，吞吐上去，公平性要另外补。</p><footer>—— 据 Rixner et al., Memory Access Scheduling, ISCA 2000；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/address-interleaving">上一课</a>决定了哪些请求碰巧同行。<a href="/cs/row-buffer-bank-conflict">行缓冲</a>给出命中价值。缺口是 <strong>调度策略</strong>：控制器队列里选下一条合法 <a href="/cs/ddr-protocol">DDR 命令</a>。FR-FCFS（first-ready, first-come first-serve）是教材与工业的基线。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>FCFS：按到达发，无视行状态，冲突与刷新插入使带宽低。FR-FCFS：在时序允许的命令里，优先选行命中（ready），同档再按到达。缺口不是再切片地址，而是队列仲裁：读优先于写（避免 load 等写突发）、写排水阈值、刷新窗口抢占。</p><p>多核：一个核的流式访问可长期占住打开行，饿死延迟敏感核——公平性扩展（PAR-BS 等）点名，本课不展开论文竞赛。</p><h3 id="fr-fcfs-不是-cpu-的-tomasulo" tabindex="-1">FR-FCFS 不是 CPU 的 Tomasulo <a class="header-anchor" href="#fr-fcfs-不是-cpu-的-tomasulo" aria-label="Permalink to &quot;FR-FCFS 不是 CPU 的 Tomasulo&quot;">​</a></h3><p>它调度的是 DRAM 命令，不是指令窗口的广播。MSHR 已把 cache 缺失变成块请求；控制器再把块拆成命令。把二者合成「乱序内存」，一致性模型会与 ROB 提交搅在一起。</p><p><span class="marginnote">Rixner et al., <em>ISCA</em> 2000 提出/普及内存访问调度与 FR-FCFS 名称。CA:AQA 收成分级存储系统。本课不发明后续 arXiv 调度器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每通道队列。合法命令集由每 bank 计时器过滤。优先：刷新到期 &gt; 行命中读 &gt; 行命中写（若写水位高则写优先）&gt; 行缺失按 FCFS。关闭页：命中优先项变少，调度更简单、平均冲突代价不同。</p>',11)),(e(),n(F,null,{default:t(()=>[c(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20MSHR%5B%22MSHR%20%E5%9D%97%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20Q%5B%22%E6%AF%8F%E9%80%9A%E9%81%93%E9%98%9F%E5%88%97%22%5D%0A%20%20Q%20--%3E%20FR%5B%22%E4%BC%98%E5%85%88%E8%A1%8C%E5%91%BD%E4%B8%AD%22%5D%0A%20%20FR%20--%3E%20CMD%5B%22%E5%90%88%E6%B3%95%20ACT%2FRD%2FWR%2FPRE%22%5D%0A%20%20CMD%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AHBM%20%E6%8A%8A%E9%80%9A%E9%81%93%E5%81%9A%E5%BE%97%E6%9B%B4%E5%AE%BD%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>与 NUMA：远程请求进另一控制器的同一类调度器，多一跳互连。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>映射改变同行概率，从而改变 FR-FCFS 的收益。QoS 计数器可限制某源的命中连击。后课持久内存的调度还要考虑写延迟不对称。本课钉 DRAM 基线。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 GPU 内存控制器的波前调度写完，不讨论侧信道（调度时序泄密）。不进入 LOB 撮合队列——名字里的 scheduling 不是交易所。</p><p>后课默认：控制器用 FR-FCFS 一类策略在合法命令中挑行命中；公平性是附加约束。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FCFS 无视行缓冲；FR-FCFS 先 ready 命中再到达序。</li><li>读写优先级与刷新插入是同一仲裁器的一部分。</li><li>吞吐与公平折中；不是 CPU 乱序内核。</li><li>出处：Rixner et al., ISCA 2000；Hennessy and Patterson, CA:AQA。</li></ul>',8))])}const _=o(f,[["render",p]]);export{u as __pageData,_ as default};
